def longest_pal_subseq(s):
    n = len(s)
    dp = [1] * n
    for i in range(n - 1, -1, -1):
        new = dp[:]
        for j in range(i + 1, n):
            if s[i] == s[j]:
                new[j] = dp[j-1] + 2 if i + 1 <= j - 1 else 2
            else:
                new[j] = max(dp[j], new[j-1])
        dp = new
    return dp[-1]
